use std::collections::{BTreeMap, BTreeSet, BinaryHeap, HashMap, VecDeque};
fn main() {
    let mut a: HashMap<u32, u32> = HashMap::new();
    let mut b: HashMap<u32, u32> = HashMap::new();
    for k in 0..1000u32 {
        a.insert(k, k);
        b.insert(k, k);
    }
