    q.push_back(2);
    q.push_back(3);
    q.push_front(1);
    println!("vecdeque: {:?}", q.iter().collect::<Vec<_>>());
    let h: BinaryHeap<i32> = [1, 5, 2, 4, 3].into_iter().collect();
